// Canada's provinces and territories as SVG paths, and the projection to place cities on them.
// Generated once (do not edit by hand) from Natural Earth 1:50m admin-1 data (public domain), via the
// sane-topojson package (MIT, © Étienne Tétreault-Pinard). Projection: Lambert conformal conic with
// Statistics Canada's parameters (standard parallels 49°N and 77°N). 5332 points.

export const CANADA_VIEW = { w: 1000, h: 863 };

/** Longitude/latitude → position on the map (same projection and fit as the outlines). */
export function project(lng: number, lat: number): [number, number] {
  const rad = Math.PI / 180;
  const rho = 1.7668328336 / Math.pow(Math.tan(Math.PI / 4 + (lat * rad) / 2), 0.9007450595);
  const t = 0.9007450595 * (lng * rad - -1.6033758120);
  const x = rho * Math.sin(t), y = 0.4820999725 - rho * Math.cos(t);
  return [8 + (x - -0.3923666280) * 1181.481755, 8 + (0.3504492624 - y) * 1181.481755];
}

